#include <stdio.h>

int power(int base, int exponent) {
    int result = 1;
    while (exponent > 0) {
        if (exponent % 2 == 1) {
            result *= base;
        }
        base *= base;
        exponent /= 2;
    }
    return result;
}

int main() {
    printf("%d %d %d\n", power(2, 10), power(3, 5), power(9, 0));
    return 0;
}
